document.head.append(Object.assign(document.createElement('style'),{textContent:authStyles}));
function can(permission){return !!state.user?.permissions?.includes(permission)}
function applyIdentity(){const u=state.user;$('#profile .avatar').textContent=u.display_name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();$('#profile strong').textContent=u.display_name;$('#profile small').textContent=u.role;$('#workspaceName').textContent=state.settings.workspace_name||'Operational orchestration';$$('.admin-only').forEach(x=>x.style.display=can('admin:access')?'':'none');$$('.new-trigger,#newRunbook').forEach(x=>x.style.display=can('runbooks:edit')?'':'none')}
async function loadVersion(){try{const res=await fetch('/health');const body=await res.json();if(body.version){$$('.sidebar-version,.login-version').forEach(el=>el.textContent=`v${body.version}`)}}catch(_){}}
function applyDashboardWidgets(){const widgets=state.user?.dashboard_widgets||['runbook_activity','today_readiness','delay_summary'];['runbook_activity','today_readiness','delay_summary'].forEach(w=>{const el=$(`#widget-${w}`);if(el)el.style.display=widgets.includes(w)?'':'none'});if(widgets.includes('delay_summary'))loadDelaySummary()}
async function loadDelaySummary(){try{const rows=await api('/api/reports/delay');const el=$('#delaySummary');if(!el)return;if(!rows.length){el.innerHTML='<p class="muted">No late or at-risk tasks.</p>';return}el.innerHTML=rows.slice(0,4).map(r=>`<div class="minirow"><span class="miniicon orange">!</span><div><b>${esc(r.task)}</b><small>${esc(r.runbook)}</small></div></div>`).join('')+(rows.length>4?`<small class="muted">+${rows.length-4} more</small>`:'')}catch(_){}}
$('#customizeDashboard').onclick=()=>{const widgets=state.user?.dashboard_widgets||['runbook_activity','today_readiness','delay_summary'];const f=$('#dashboardCustomizeForm');['runbook_activity','today_readiness','delay_summary'].forEach(w=>{f.elements[w].checked=widgets.includes(w)});$('#dashboardCustomizeModal').showModal()};
$$('.close-dashboard-customize').forEach(b=>b.onclick=()=>$('#dashboardCustomizeModal').close());
$('#dashboardCustomizeForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;const widgets=['runbook_activity','today_readiness','delay_summary'].filter(w=>f.elements[w].checked);try{await api('/api/me/dashboard',{method:'PATCH',body:JSON.stringify({widgets})});state.user.dashboard_widgets=widgets;applyDashboardWidgets();$('#dashboardCustomizeModal').close();toast('Dashboard updated')}catch(err){toast(err.message,true)}};
async function enterWorkspace(session){state.user=session.user;state.csrf=session.user.csrf_token;state.settings=session.settings;$('#loginScreen').classList.add('hidden');$('.shell').classList.remove('app-hidden');applyIdentity();applyDashboardWidgets();loadSavedViews();load()}
async function boot(){loadVersion();try{const session=await api('/api/auth/me');await enterWorkspace(session)}catch(_){try{await api('/api/auth/sso',{method:'POST',body:'{}'});const session=await api('/api/auth/me');await enterWorkspace(session)}catch(__){$('#loginScreen').classList.remove('hidden')}}}
$('#loginForm').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));try{state.user=await api('/api/auth/login',{method:'POST',body:JSON.stringify(values)});state.csrf=state.user.csrf_token;const session=await api('/api/auth/me');state.user=session.user;state.settings=session.settings;$('#loginScreen').classList.add('hidden');$('.shell').classList.remove('app-hidden');applyIdentity();applyDashboardWidgets();loadSavedViews();await load();toast(`Welcome, ${state.user.display_name}`)}catch(err){toast(err.message,true)}};
$('#logout').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch(_){}state.user=null;state.csrf='';$('.shell').classList.add('app-hidden');$('#loginScreen').classList.remove('hidden')};
function renderRoles(){const roles={'View runbooks':[1,1,1,1,1,1,1],'Create and edit runbooks':[1,1,0,0,1,0,0],'Execute assigned tasks':[1,1,1,0,1,1,1],'Sync ServiceOps':[1,1,0,0,1,0,0],'Manage users and sessions':[1,0,0,0,0,0,0],'Platform settings and connections':[1,0,0,0,0,0,0],'View tenant audit and health':[1,0,0,0,0,0,0]},names=['Admin','Editor','Member','Stakeholder','Workspace Manager','Folder Creator','Stream Editor'];$('#roleMatrix').innerHTML=`<div class="role-row head"><span>Privilege</span>${names.map(x=>`<span>${x}</span>`).join('')}</div>`+Object.entries(roles).map(([p,v])=>`<div class="role-row"><b>${p}</b>${v.map(x=>`<span class="${x?'role-yes':'role-no'}">${x?'✓':'—'}</span>`).join('')}</div>`).join('')}
