const baseRenderDetail=renderDetail;
renderDetail=function(){baseRenderDetail();const r=state.current,taskRoot=$('#tasks');if(!taskRoot)return;$$('.task',taskRoot).forEach((el,i)=>{el.classList.add(`status-${r.tasks[i]?.status||'pending'}`)});const owners=[...new Set(r.tasks.map(t=>t.owner_display||t.owner||'Unassigned'))].sort();const statuses=[...new Set(r.tasks.map(t=>t.status))].sort();const applyFilters=()=>$$('.task',taskRoot).forEach((el,i)=>{const t=r.tasks[i];const visible=(activeStream==='All'||t.stream===activeStream)&&(activeOwner==='All'||(t.owner_display||t.owner||'Unassigned')===activeOwner)&&(activeStatus==='All'||t.status===activeStatus);el.style.display=visible?'':'none'});const controls=document.createElement('div');controls.innerHTML=`<div class="view-switch"><button class="active" data-mode="timeline">☷ Timeline</button><button data-mode="map">⌘ Node map</button></div><div class="stream-strip"><button class="stream-pill ${activeStream==='All'?'active':''}" data-stream="All">All <b>${r.tasks.length}</b></button>${r.streams.map(s=>`<span class="stream-pill-group"><button class="stream-pill ${activeStream===s.name?'active':''}" data-stream="${esc(s.name)}" title="Filter by ${esc(s.name)}">${esc(s.name)} <b>${s.task_count}</b></button><button class="stream-edit" data-stream-rename="${s.id}" data-stream-name="${esc(s.name)}" aria-label="Rename or delete ${esc(s.name)} stream">✎</button></span>`).join('')}<button class="stream-pill stream-add" data-stream-add title="Add a stream">＋</button><label class="task-filter">Owner <select data-owner-filter><option value="All">All</option>${owners.map(o=>`<option value="${esc(o)}" ${activeOwner===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label><label class="task-filter">Status <select data-status-filter><option value="All">All</option>${statuses.map(s=>`<option value="${esc(s)}" ${activeStatus===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label></div>`;taskRoot.parentNode.insertBefore(controls,taskRoot);const ownerSelect=$('[data-owner-filter]',controls);if(ownerSelect)ownerSelect.onchange=()=>{activeOwner=ownerSelect.value;applyFilters()};const statusSelect=$('[data-status-filter]',controls);if(statusSelect)statusSelect.onchange=()=>{activeStatus=statusSelect.value;applyFilters()};$$('[data-stream]',controls).forEach(b=>{b.onclick=()=>{activeStream=b.dataset.stream;$$('[data-stream]',controls).forEach(x=>x.classList.toggle('active',x===b));applyFilters()}});$$('[data-stream-rename]',controls).forEach(b=>{b.onclick=async()=>{const next=prompt('Rename stream (clear the field and confirm to delete an empty stream)',b.dataset.streamName);if(next===null||next===b.dataset.streamName)return;try{state.current=next.trim()?await api(`/api/streams/${b.dataset.streamRename}`,{method:'PATCH',body:JSON.stringify({name:next.trim()})}):await api(`/api/streams/${b.dataset.streamRename}`,{method:'DELETE'});renderDetail()}catch(e){toast(e.message,true)}}});const addStream=$('[data-stream-add]',controls);if(addStream)addStream.onclick=async()=>{const name=prompt('New stream name');if(!name)return;try{state.current=await api(`/api/runbooks/${r.id}/streams`,{method:'POST',body:JSON.stringify({name})});renderDetail()}catch(e){toast(e.message,true)}};$$('[data-mode]',controls).forEach(b=>b.onclick=()=>{$$('[data-mode]',controls).forEach(x=>x.classList.toggle('active',x===b));if(b.dataset.mode==='timeline'){taskRoot.innerHTML=r.tasks.map((t,i)=>taskHtml(t,i,new Set(r.critical_path).has(t.id))).join('');$$('.task',taskRoot).forEach((el,i)=>el.classList.add(`status-${r.tasks[i].status}`));$$('.task-actions button',taskRoot).forEach(x=>x.onclick=()=>transitionTask(x.dataset.id,x.dataset.status))}else{const byId={};r.tasks.forEach(t=>byId[t.id]=t);const level={};const levelOf=id=>{if(level[id]!==undefined)return level[id];const t=byId[id];const l=t&&t.depends_on.length?1+Math.max(...t.depends_on.map(levelOf)):0;level[id]=l;return l};r.tasks.forEach(t=>levelOf(t.id));const maxLevel=Math.max(0,...r.tasks.map(t=>level[t.id]));const critical=new Set(r.critical_path||[]);const cols=[];for(let l=0;l<=maxLevel;l++){const nums={};r.tasks.forEach((t,i)=>nums[t.id]=i+1);const colTasks=r.tasks.filter(t=>level[t.id]===l);cols.push(`<div class="node-col"><span class="node-col-label">Step ${l+1}</span>${colTasks.map(t=>`<div class="node ${esc(t.status)} ${critical.has(t.id)?'critical':''}"><em>${esc(t.stream)}</em><b>#${nums[t.id]} ${esc(t.title)}</b><span>${esc(t.owner||'Unassigned')} · ${t.duration} min</span><small>${t.depends_on.length?'Depends on task'+(t.depends_on.length>1?'s ':' ')+t.depends_on.join(', '):'Entry point'} · ${esc(t.status)}</small>${critical.has(t.id)?'<span class="node-critical-badge">Critical path</span>':''}</div>`).join('')}</div>`)}taskRoot.innerHTML=`<div class="node-map">${cols.join('')}</div>`}});applyFilters()};
