async function loadAdmin(){if(!can('admin:access'))return;try{const [users,settings,workspaces]=await Promise.all([api('/api/admin/users'),api('/api/admin/settings'),api('/api/admin/workspaces')]);const root=$('#usersTable');root.innerHTML='<div class="user-row head admin-user-row"><span></span><span>Identity</span><span>Effective role</span><span>Team</span><span>Controls</span></div>'+users.map(u=>`<div class="user-row admin-user-row" data-user="${u.id}"><span class="user-avatar">${esc(u.display_name.split(/\s+/).map(x=>x[0]).join('').slice(0,2))}</span><div><b>${esc(u.display_name)}</b><small>${esc(u.email)} · @${esc(u.username)}</small></div><select class="role-select" data-role="${u.id}">${['Admin','Editor','Member','Stakeholder','Workspace Manager','Folder Creator','Stream Editor'].map(r=>`<option ${u.role===r?'selected':''}>${r}</option>`).join('')}</select><span>${esc(u.team||'Unassigned')}</span><div class="user-actions"><button data-reset="${u.id}" title="Reset password">⌁</button><button data-toggle="${u.id}" data-active="${u.active}" title="${u.active?'Disable':'Enable'}">${u.active?'⊘':'✓'}</button><button class="danger" data-delete="${u.id}" title="Delete">×</button></div></div>`).join('');$$('[data-role]',root).forEach(x=>x.onchange=()=>updateUser(x.dataset.role,{role:x.value}));$$('[data-toggle]',root).forEach(x=>x.onclick=()=>updateUser(x.dataset.toggle,{active:x.dataset.active!=='1'}));$$('[data-reset]',root).forEach(x=>x.onclick=()=>{const password=prompt('Enter a new temporary password (minimum 12 characters)');if(password)updateUser(x.dataset.reset,{password})});$$('[data-delete]',root).forEach(x=>x.onclick=()=>{if(confirm('Permanently delete this user?'))deleteUser(x.dataset.delete)});const f=$('#settingsForm');Object.entries(settings).forEach(([k,v])=>{if(f.elements[k])f.elements[k].type==='checkbox'?f.elements[k].checked=v==='true':f.elements[k].value=v});$('#deliveryStatus').innerHTML=`<article class="panel settings-form"><h2>Email delivery</h2><div class="kv"><span>SMTP delivery</span><b class="${settings.mail_delivery_configured==='true'?'green':''}">${settings.mail_delivery_configured==='true'?'Configured':'Server configuration required'}</b></div><div class="kv"><span>Sender</span><b>${esc(settings.mail_sender||'Not configured')}</b></div><div class="kv"><span>Public FlowOps URL</span><b>${settings.public_url_configured==='true'?'Configured':'Not configured'}</b></div><p class="muted">SMTP credentials remain deployment-managed secrets. Invitation and reset messages never expose their tokens through the admin API.</p></article>`;let area=$('#workspaceControl');if(!area){area=document.createElement('div');area.id='workspaceControl';area.className='control-grid';$('#adminUsers').append(area)}area.innerHTML=`<article class="panel"><div class="admin-section-title"><div><h2>Workspaces</h2><p>Real isolation containers for runbooks and teams.</p></div><span class="chip">${workspaces.length} total</span></div>${workspaces.map(w=>`<div class="workspace-card"><i class="workspace-color" style="background:${esc(w.color)}"></i><div><b>${esc(w.name)}</b><small>${esc(w.description||'No description')}</small></div><span class="chip">${w.runbook_count} runbooks</span></div>`).join('')}</article><article class="panel"><h2>Invite user</h2><p>Generate a seven-day, single-purpose invitation for secure delivery.</p><form id="inviteForm"><label>Email<input name="email" type="email" required placeholder="person@example.com"></label><label>Role<select name="role"><option>Member</option><option>Editor</option><option>Admin</option></select></label><button class="primary">Create invitation</button></form><hr><h2>Create workspace</h2><form id="workspaceForm"><label>Name<input name="name" required placeholder="e.g. Trading Infrastructure"></label><label>Description<input name="description"></label><label>Color<input name="color" type="color" value="#3157e0"></label><button class="primary">Create workspace</button></form></article>`;$('#inviteForm').onsubmit=inviteUser;$('#workspaceForm').onsubmit=createWorkspace;renderRoles()}catch(e){toast(e.message,true)}};
