function fmtTime(iso){try{return new Date(iso).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}catch(e){return ''}}
const directTransitionTask=transitionTask;transitionTask=async function(id,status){const task=state.current.tasks.find(t=>t.id==id),payload={status};if(status==='blocked')payload.blocked_reason=prompt('Why is this task blocked?')||'';if(task?.task_type==='validation'&&status==='complete'){const result=prompt('Validation result: Pass, Fail, or Not Tested','Pass');if(!result)return;payload.validation_result=result;payload.validation_comment=prompt('Validation evidence or commentary (optional)','')||''}if(task?.task_type==='automation'&&status==='skipped'){const reason=prompt('Audited reason for skipping this failed automation task:');if(!reason)return;payload.skip_reason=reason}try{state.current=await api(`/api/tasks/${id}`,{method:'PATCH',body:JSON.stringify(payload)});renderDetail();await load();toast(status==='running'&&task?.task_type==='automation'?'Automation task triggered':`Task marked ${status}`)}catch(e){toast(e.message,true)}};
