const activity=[];let unread=0;const drawer=document.createElement('section');drawer.className='notification-drawer';drawer.setAttribute('aria-label','Activity notifications');drawer.innerHTML='<div class="notification-head"><h2>Live activity</h2><button id="clearActivity">Clear</button></div><div class="notification-list"><div class="notification-empty">Activity from your workspace will appear here.</div></div>';document.body.append(drawer);const bell=$$('.header-actions .icon')[1];const count=document.createElement('span');count.className='unread-count';count.hidden=true;bell.append(count);bell.onclick=()=>{drawer.classList.toggle('open');unread=0;count.hidden=true};$('#clearActivity').onclick=()=>{activity.length=0;renderActivity()};
function renderActivity(){const list=$('.notification-list',drawer);list.innerHTML=activity.length?activity.slice(0,30).map(n=>`<div class="notification-item"><span class="notification-glyph">${n.action.includes('task')?'✓':n.action.includes('comment')?'◌':'↗'}</span><div><p><b>${esc(n.actor||'FlowOps')}</b> · ${esc(n.detail||n.action)}</p><small>${esc(n.action)} · ${fmt(n.created_at)}</small></div></div>`).join(''):'<div class="notification-empty">No recent workspace activity.</div>'}
function announceActivity(event){let data;try{data=JSON.parse(event.data)}catch(_){return}activity.unshift(data);unread++;count.textContent=unread>9?'9+':unread;count.hidden=false;renderActivity();if(!data.action.startsWith('auth.'))toast(`${data.actor}: ${data.detail}`)}
liveRefresh=function(event){if(event)announceActivity(event);if(liveTimer)clearTimeout(liveTimer);liveTimer=setTimeout(async()=>{try{const before=new Set((state.current?.tasks||[]).filter(t=>!t.blocked&&t.status==='pending').map(t=>t.id));await load();if(state.current&&$('#detail').classList.contains('active')){state.current=await api(`/api/runbooks/${state.current.id}`);const newlyReady=state.current.tasks.filter(t=>!t.blocked&&t.status==='pending'&&!before.has(t.id));renderDetail();newlyReady.forEach(t=>{activity.unshift({action:'task.ready',actor:'FlowOps',detail:`${t.title} is ready to start`,created_at:new Date().toISOString()});unread++;renderActivity()})}document.body.classList.add('activity-flash');setTimeout(()=>document.body.classList.remove('activity-flash'),700)}catch(e){if(!/Authentication/.test(e.message))toast(e.message,true)}},120)};
ensureLive=function(){if(!state.user||liveFeed)return;liveFeed=new EventSource('/api/events');const badge=$('.live-state');liveFeed.addEventListener('workspace',liveRefresh);liveFeed.onopen=()=>{badge.classList.remove('reconnecting');badge.querySelector('span').textContent='Live updates'};liveFeed.onerror=()=>{badge.classList.add('reconnecting');badge.querySelector('span').textContent='Reconnecting…'}};
const animatedRenderDetail=renderDetail;renderDetail=function(){animatedRenderDetail();if(!state.current)return;$$('#tasks .task').forEach((el,i)=>{const task=state.current.tasks[i];if(!task)return;if(task.status==='running'&&task.started_at){const timer=document.createElement('span');timer.className='live-timer';timer.dataset.started=task.started_at;el.querySelector('small')?.append(timer)}});if(state.current.status==='live'){const banner=document.createElement('div');banner.className='live-command-banner';banner.innerHTML='<i></i><b>LIVE EXECUTION</b><span>Changes and task timing are broadcasting to all participants.</span><time id="runElapsed">00:00:00</time>';$('#detailContent').prepend(banner)}};
setInterval(()=>{$$('[data-started]').forEach(el=>{const seconds=Math.max(0,Math.floor((Date.now()-new Date(el.dataset.started).getTime())/1000));el.textContent=`● ${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`});const elapsed=$('#runElapsed');if(elapsed&&state.current){const starts=state.current.tasks.map(t=>t.started_at&&new Date(t.started_at).getTime()).filter(Boolean);if(starts.length){const s=Math.floor((Date.now()-Math.min(...starts))/1000);elapsed.textContent=`${String(Math.floor(s/3600)).padStart(2,'0')}:${String(Math.floor(s%3600/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}}},1000);
function showGoLive(){const overlay=document.createElement('div');overlay.className='go-live-overlay';overlay.innerHTML='<div class="go-live-card"><div class="go-live-ring"><b>LIVE</b></div><h2>Runbook is live</h2><p>Participants are connected. Execution timing has started.</p><div class="go-live-track"><i></i></div></div>';document.body.append(overlay);setTimeout(()=>{overlay.style.opacity='0';overlay.style.transition='.3s';setTimeout(()=>overlay.remove(),300)},2100)}
transitionRunbook=async function(status){try{state.current=await api(`/api/runbooks/${state.current.id}/transition`,{method:'POST',body:JSON.stringify({status})});renderDetail();await load();if(status==='live')showGoLive();else toast(`Runbook moved to ${status}`)}catch(e){toast(e.message,true)}};
const drawActivity=renderActivity;renderActivity=function(){drawActivity();count.textContent=unread>9?'9+':unread;count.hidden=unread===0};
const timingStyles=`.run-timing{--timing-color:#3157e0;position:relative;overflow:hidden;margin:18px 0;background:#fff;border:1px solid var(--line);border-radius:12px;display:grid;grid-template-columns:minmax(210px,.75fr) minmax(360px,1.65fr) minmax(170px,.6fr);box-shadow:0 7px 22px #1a2d5010}.run-timing:before{content:'';position:absolute;inset:0 auto 0 0;width:4px;background:var(--timing-color)}.run-timing-main,.run-timing-track,.run-timing-side{padding:17px 20px}.run-timing-main{border-right:1px solid var(--line)}.run-timing-kicker{display:flex;align-items:center;gap:7px;color:#68768b;font-size:9px;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.run-timing-dot{width:7px;height:7px;border-radius:50%;background:var(--timing-color)}.run-timing-clock{display:block;margin-top:5px;color:#17233a;font-size:27px;line-height:1.1;font-variant-numeric:tabular-nums;letter-spacing:-.025em}.run-timing-caption,.run-timing-side small{display:block;color:var(--muted);font-size:10px;margin-top:5px}.run-timing-track{display:flex;flex-direction:column;justify-content:center}.timing-labels{display:flex;justify-content:space-between;gap:15px;color:#66758b;font-size:10px}.timing-labels b{color:#25334a}.timing-rail{height:7px;background:#edf0f5;border-radius:9px;margin:13px 0 8px;position:relative;overflow:visible}.timing-fill{display:block;height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,#3157e0,var(--timing-color));transition:width .7s ease,background .3s}.timing-marker{position:absolute;top:50%;left:0;width:15px;height:15px;background:white;border:4px solid var(--timing-color);border-radius:50%;transform:translate(-50%,-50%);transition:left .7s ease;box-shadow:0 2px 8px #1d31502b}.timing-foot{display:flex;justify-content:space-between;color:#8a95a7;font-size:9px}.run-timing-side{border-left:1px solid var(--line);display:flex;flex-direction:column;justify-content:center}.run-timing-side b{font-size:13px;color:#2d3a50}.run-timing.start_due{--timing-color:#e5a332}.run-timing.start_due .run-timing-dot,.run-timing.overdue .run-timing-dot,.run-timing.live .run-timing-dot{animation:timingPulse 1.6s ease-in-out infinite}.run-timing.overdue,.run-timing.overrun{--timing-color:#db5965}.run-timing.live{--timing-color:#24ae7d}.run-timing.live .timing-fill{background:linear-gradient(90deg,#3157e0,#24ae7d,#3157e0);background-size:200% 100%;animation:timingFlow 2.5s linear infinite}.run-timing.paused{--timing-color:#e5a332}.run-timing.complete{--timing-color:#24ae7d;background:linear-gradient(90deg,#f7fffb,#fff 42%)}@keyframes timingPulse{50%{transform:scale(1.55);box-shadow:0 0 0 5px color-mix(in srgb,var(--timing-color) 15%,transparent)}}@keyframes timingFlow{to{background-position:-200% 0}}@media(max-width:920px){.run-timing{grid-template-columns:1fr 1.5fr}.run-timing-side{grid-column:1/-1;border-left:0;border-top:1px solid var(--line);padding-block:11px}}@media(max-width:650px){.run-timing{grid-template-columns:1fr}.run-timing-main{border-right:0;border-bottom:1px solid var(--line)}.run-timing-side{grid-column:auto}}@media(prefers-reduced-motion:reduce){.run-timing-dot,.run-timing .timing-fill{animation:none!important}.timing-fill,.timing-marker{transition:none!important}}`;
document.head.append(Object.assign(document.createElement('style'),{textContent:timingStyles}));
let timingAnchor={client:0,server:0};
function durationClock(seconds,days=true){seconds=Math.max(0,Math.floor(Math.abs(seconds||0)));const d=Math.floor(seconds/86400),h=Math.floor(seconds%86400/3600),m=Math.floor(seconds%3600/60),s=seconds%60;if(days&&d)return `${d}d ${String(h).padStart(2,'0')}h ${String(m).padStart(2,'0')}m`;return `${String(h+d*24).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`}
function timingSnapshot(){const t=state.current?.timing;if(!t)return null;const serverNow=timingAnchor.server+(Date.now()-timingAnchor.client),scheduled=t.scheduled_at?new Date(t.scheduled_at).getTime():0,started=t.actual_started_at?new Date(t.actual_started_at).getTime():0,completed=t.actual_completed_at?new Date(t.actual_completed_at).getTime():0;const elapsed=started?Math.max(0,Math.floor(((completed||serverNow)-started)/1000)):0,toStart=scheduled?Math.floor((scheduled-serverNow)/1000):null,planned=t.planned_seconds||0;let phase=t.phase;if(!started&&toStart!==null)phase=toStart<0?'overdue':toStart<=900?'start_due':'upcoming';return {...t,phase,elapsed,toStart,planned,variance:started?elapsed-planned:null}}
function renderTimingPanel(){const t=state.current?.timing,metrics=$('#detailContent .metrics');if(!t||!metrics)return;timingAnchor={client:Date.now(),server:new Date(t.server_now).getTime()||Date.now()};const panel=document.createElement('section');panel.id='runTiming';panel.className=`run-timing ${esc(t.phase)}`;panel.setAttribute('aria-live','polite');panel.innerHTML='<div class="run-timing-main"><span class="run-timing-kicker"><i class="run-timing-dot"></i><span id="timingKicker">RUNBOOK TIMING</span></span><strong class="run-timing-clock" id="timingClock">--:--:--</strong><small class="run-timing-caption" id="timingCaption"></small></div><div class="run-timing-track"><div class="timing-labels"><span><b>Window progress</b></span><span id="timingProgress">0%</span></div><div class="timing-rail"><i class="timing-fill" id="timingFill"></i><i class="timing-marker" id="timingMarker"></i></div><div class="timing-foot"><span id="timingStart">Start —</span><span id="timingEnd">Planned end —</span></div></div><div class="run-timing-side"><b id="timingVariance">Planned duration</b><small id="timingVarianceNote"></small></div>';metrics.before(panel);tickRunTiming()}
function tickRunTiming(){const panel=$('#runTiming'),x=timingSnapshot();if(!panel||!x)return;let kicker='RUNBOOK TIMING',clock='Not scheduled',caption='Set a scheduled start to activate the countdown',variance=`${durationClock(x.planned,false)} planned`,varianceNote='Dependency-aware execution window',progress=0,phase=x.phase;if(['upcoming','start_due'].includes(phase)){kicker=phase==='start_due'?'STARTING SOON':'STARTS IN';clock=durationClock(x.toStart);caption=`Scheduled ${fmt(x.scheduled_at)}`}else if(phase==='overdue'){kicker='START OVERDUE BY';clock=durationClock(x.toStart);caption=`Was scheduled ${fmt(x.scheduled_at)}`}else if(['live','paused'].includes(phase)){kicker=phase==='paused'?'EXECUTION PAUSED · ELAPSED':'LIVE · ELAPSED';clock=durationClock(x.elapsed,false);caption=`Started ${fmt(x.actual_started_at)}`;progress=x.planned?Math.min(100,x.elapsed/x.planned*100):0;if(x.variance>0){phase='overrun';variance=`${durationClock(x.variance,false)} over plan`;varianceNote='Planned window has been exceeded'}else{variance=`${durationClock(-x.variance,false)} remaining`;varianceNote='Against the planned execution window'}}else if(phase==='complete'){kicker='COMPLETED · ACTUAL DURATION';clock=durationClock(x.elapsed,false);caption=`Finished ${fmt(x.actual_completed_at)}`;progress=100;variance=x.variance>0?`${durationClock(x.variance,false)} over plan`:`${durationClock(-x.variance,false)} under plan`;varianceNote='Final planned-versus-actual variance'}panel.className=`run-timing ${phase}`;$('#timingKicker').textContent=kicker;$('#timingClock').textContent=clock;$('#timingCaption').textContent=caption;$('#timingVariance').textContent=variance;$('#timingVarianceNote').textContent=varianceNote;$('#timingProgress').textContent=x.actual_started_at?`${Math.round(progress)}% of window`:'Awaiting start';$('#timingFill').style.width=`${progress}%`;$('#timingMarker').style.left=`${progress}%`;$('#timingStart').textContent=x.actual_started_at?`Actual ${fmt(x.actual_started_at)}`:`Start ${fmt(x.scheduled_at)}`;const end=x.actual_started_at&&x.planned?new Date(new Date(x.actual_started_at).getTime()+x.planned*1000).toISOString():x.scheduled_at&&x.planned?new Date(new Date(x.scheduled_at).getTime()+x.planned*1000).toISOString():null;$('#timingEnd').textContent=`Planned end ${fmt(end)}`;const elapsed=$('#runElapsed');if(elapsed&&x.actual_started_at)elapsed.textContent=durationClock(x.elapsed,false)}
const timedRenderDetail=renderDetail;renderDetail=function(){timedRenderDetail();renderTimingPanel()};
setInterval(tickRunTiming,1000);
const integrationStyles=`.integration-hero{background:linear-gradient(125deg,#132048,#3157e0 58%,#2541b8);color:white;border-radius:14px;padding:28px;display:grid;grid-template-columns:1.2fr .8fr;gap:30px;box-shadow:0 14px 35px #2541b824}.integration-hero h2{font-size:24px;margin:7px 0}.integration-hero p{color:#d9e4ff;max-width:650px}.system-boundary{display:grid;grid-template-columns:1fr 45px 1fr;align-items:center;background:#ffffff12;border:1px solid #ffffff1f;border-radius:11px;padding:16px}.system-boundary>span{text-align:center;font-size:22px}.system-node{background:#fff;color:#1e2b42;border-radius:9px;padding:14px}.system-node small{display:block;color:#718096;margin-top:4px}.integration-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:18px}.connection-card{padding:0!important;overflow:hidden}.connection-head{display:flex;align-items:center;gap:12px;padding:19px 21px;border-bottom:1px solid var(--line)}.provider-icon{width:39px;height:39px;border-radius:9px;display:grid;place-items:center;background:#eaf0ff;color:#3157e0;font-weight:850}.provider-icon.jenkins{background:#fff0e9;color:#c85e32}.connection-head div{flex:1}.connection-head h2{margin:0;font-size:15px}.connection-head p{margin:2px 0 0;color:var(--muted);font-size:10px}.connection-state{display:flex;align-items:center;gap:6px;font-size:10px;font-weight:750}.connection-state i{width:7px;height:7px;border-radius:50%;background:#9aa5b4}.connection-state.ready i{background:#25b985}.connection-body{padding:20px}.ownership-list{display:grid;gap:9px}.ownership-item{display:grid;grid-template-columns:25px 1fr;gap:8px}.ownership-item i{width:21px;height:21px;border-radius:50%;background:#edf2ff;color:#3157e0;display:grid;place-items:center;font-style:normal;font-size:10px}.ownership-item small{display:block;color:var(--muted)}.connection-form{display:grid;gap:13px}.connection-form .toggle{padding:10px 12px}.credential-banner{display:flex;justify-content:space-between;gap:10px;background:#f5f7fa;border:1px solid #e4e9ef;border-radius:7px;padding:11px}.credential-banner b{font-size:11px}.credential-banner small{display:block;color:var(--muted)}.safe-badge{color:#17855e;font-size:9px;font-weight:800}.form-actions{display:flex;gap:8px;align-items:center}.test-result{font-size:10px;color:var(--muted)}.video-findings{margin-top:18px}.finding-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin-top:13px}.finding{background:#f6f8fb;border:1px solid #e7ebf1;border-radius:8px;padding:12px}.finding b{font-size:11px;display:block}.finding small{color:var(--muted)}@media(max-width:1000px){.integration-hero,.integration-grid{grid-template-columns:1fr}.finding-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.system-boundary{grid-template-columns:1fr}.system-boundary>span{transform:rotate(90deg)}.finding-grid{grid-template-columns:1fr}}`;
document.head.append(Object.assign(document.createElement('style'),{textContent:integrationStyles}));
const boolValue=v=>v===true||v==='true';
const settingsSubmit=$('#settingsForm button[type="submit"],#settingsForm button.primary');if(settingsSubmit&&!$('#directorySettings')){const directory=document.createElement('section');directory.id='directorySettings';directory.innerHTML='<hr><h2>Sign-in and directory</h2><p class="muted">Local administrator is always available. Directory credentials are verified by the AD/LDAP provider already configured in ServiceOps.</p><label class="toggle"><input name="directory_enabled" type="checkbox"> Enable ServiceOps AD/LDAP sign-in</label><label>AD domain name<input name="directory_domain" placeholder="corp.example.com"><small>Shown as the authentication source and used in the username example, matching ServiceOps.</small></label>';settingsSubmit.before(directory)}
function integrationOverviewHtml(){return `<section class="integration-hero"><div><span class="eyebrow light">GOVERNED EXECUTION</span><h2>One operational lifecycle. Two clear authorities.</h2><p>ServiceOps approves and governs the change. FlowOps converts that approved intent into dependency-aware work, live coordination, and timestamped execution evidence.</p></div><div class="system-boundary"><div class="system-node"><b>ServiceOps</b><small>Requests · risk · approvals · CMDB · closure</small></div><span>⇄</span><div class="system-node"><b>FlowOps</b><small>Plans · teams · dependencies · live tasks · evidence</small></div></div></section><div class="integration-grid"><article class="panel"><h2>ServiceOps → FlowOps</h2><div class="ownership-list"><div class="ownership-item"><i>1</i><div><b>Approved change starts orchestration</b><small>Link a governed ticket before a runbook moves live.</small></div></div><div class="ownership-item"><i>2</i><div><b>Context follows the work</b><small>Ticket, service, owner, risk, and planned window remain correlated.</small></div></div></div></article><article class="panel"><h2>FlowOps → ServiceOps</h2><div class="ownership-list"><div class="ownership-item"><i>3</i><div><b>Execution state returns live</b><small>Start, delays, failures, completion, and evidence update the record.</small></div></div><div class="ownership-item"><i>4</i><div><b>Governance stays authoritative</b><small>FlowOps never bypasses ServiceOps approval or lifecycle policy.</small></div></div></div></article></div>`}
function renderIntegrationOverview(){const root=$('#integrationOverview');if(root)root.innerHTML=integrationOverviewHtml()}
function connectionForm(provider,c){const configured=c.credential_configured,managed=c.credential_source==='Encrypted FlowOps setting';return `<article class="panel connection-card serviceops-only"><div class="connection-head"><span class="provider-icon">SO</span><div><h2>ServiceOps</h2><p>REST API v1 · governance and ITSM system of record</p></div><span class="connection-state ${configured?'ready':''}"><i></i>${configured?'API key ready':'API key required'}</span></div><form class="connection-body connection-form" data-connection="serviceops"><div class="callout"><b>Create the key in ServiceOps</b><ol><li>Open <b>Administration → API access</b>.</li><li>Create a client named <b>FlowOps</b> and select its acting user.</li><li>Grant <code>tickets:read</code>, <code>tickets:update</code>, and <code>workflows:execute</code> when workflow triggering is enabled.</li><li>Copy the one-time <code>sop_…</code> token and paste it below.</li></ol></div><label>ServiceOps URL<input name="url" value="${esc(c.url||'')}" placeholder="http://serviceops.operations.svc.cluster.local"><small>For MicroK8s use the internal service URL. The public Cloudflare Access URL returns an HTML login page to server requests.</small></label><label>ServiceOps API key<input name="credential" type="password" autocomplete="new-password" placeholder="${configured?'Leave blank to keep the saved key':'Paste the sop_… key from ServiceOps'}" ${c.credential_editable?'':'disabled'}><small>${c.credential_editable?'Encrypted at rest and never returned to the browser.':'Credential encryption is not configured on this FlowOps deployment.'}</small></label><label class="toggle"><input name="enabled" type="checkbox" ${boolValue(c.enabled)?'checked':''}> Enable ServiceOps integration</label><label class="toggle"><input name="require_approved" type="checkbox" ${boolValue(c.require_approved)?'checked':''}> Require an approved ServiceOps change before Live</label><label class="toggle"><input name="sync_on_live" type="checkbox" ${boolValue(c.sync_on_live)?'checked':''}> Update linked change to In Progress on Live</label><label class="toggle"><input name="sync_on_complete" type="checkbox" ${boolValue(c.sync_on_complete)?'checked':''}> Resolve linked change when the runbook completes</label><label class="toggle"><input name="trigger_workflow" type="checkbox" ${boolValue(c.trigger_workflow)?'checked':''}> Trigger the linked ServiceOps workflow on Live</label><div class="credential-banner"><div><b>Encrypted API key</b><small>${esc(c.credential_source)} · readback disabled</small></div><span class="safe-badge">${configured?'CONFIGURED':'NOT SET'}</span></div><div class="form-actions"><button class="primary">Save connection</button><button type="button" class="secondary" data-test="serviceops">Test ServiceOps API</button>${managed?'<button type="button" class="secondary danger" data-revoke="serviceops">Revoke API key</button>':''}<span class="test-result" id="serviceopsTest"></span></div></form></article>`}
async function loadConnections(){if(!can('admin:settings'))return;const data=await api('/api/admin/integrations');$('#connectionAdmin').innerHTML=`<div class="pagehead"><div><span class="eyebrow">SERVICEOPS CONNECTION</span><h2>ServiceOps integration</h2><p>Configure the API endpoint, encrypted key, approval gate, and lifecycle synchronization without editing deployment files.</p></div></div>${connectionForm('serviceops',data.serviceops)}`;$$('[data-connection]').forEach(form=>form.onsubmit=saveConnection);$$('[data-test]').forEach(button=>button.onclick=()=>testConnection(button.dataset.test));$$('[data-revoke]').forEach(button=>button.onclick=()=>revokeCredential(button.dataset.revoke))}
async function saveConnection(e){e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));data.provider='serviceops';$$('input[type=checkbox]',form).forEach(x=>data[x.name]=x.checked);try{await api('/api/admin/integrations',{method:'POST',body:JSON.stringify(data)});await loadConnections();toast('ServiceOps connection saved')}catch(err){toast(err.message,true)}}
async function revokeCredential(provider){if(!confirm('Revoke the stored ServiceOps API key?'))return;try{await api('/api/admin/integrations',{method:'POST',body:JSON.stringify({provider:'serviceops',revoke_credential:true})});await loadConnections();toast('ServiceOps API key revoked')}catch(err){toast(err.message,true)}}
const adminCapabilityStyles=`.admin-capability-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}.admin-capability{border:1px solid var(--line);border-radius:10px;background:white;padding:18px;text-align:left;display:grid;grid-template-columns:40px 1fr;gap:12px;color:var(--ink)}.admin-capability:hover{border-color:#8da7df;box-shadow:0 5px 18px #1f3b7610}.admin-capability>span{width:40px;height:40px;border-radius:9px;background:#eaf0ff;color:#3157e0;display:grid;place-items:center;font-weight:800}.admin-capability h3{margin:0 0 5px}.admin-capability p{margin:0;color:var(--muted);font-size:12px}.admin-list-row{display:grid;grid-template-columns:1.2fr 1fr 1fr auto;gap:12px;align-items:center;padding:12px 0;border-bottom:1px solid var(--line)}.admin-list-row small{display:block;color:var(--muted)}.admin-list-row .inline-actions{display:flex;gap:6px}.audit-row{padding:11px 0;border-bottom:1px solid var(--line)}.audit-row small{display:block;color:var(--muted);margin-top:4px}.health-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px}.health-metric{background:#f6f8fc;border-radius:9px;padding:15px}.health-metric span{display:block;color:var(--muted);font-size:11px}.health-metric b{display:block;font-size:22px;margin-top:5px}`;document.head.append(Object.assign(document.createElement('style'),{textContent:adminCapabilityStyles}));
async function loadAdminPanel(name){try{if(name==='connections')return loadConnections();if(name==='sessions'){const sessions=await api('/api/admin/sessions');$('#sessionAdmin').innerHTML=`<div class="panelhead"><div><h2>Active sessions</h2><p>Revoke access immediately without disabling the user.</p></div><span class="chip">${sessions.length} active</span></div>${sessions.map(s=>`<div class="admin-list-row"><div><b>${esc(s.display_name)}</b><small>@${esc(s.username)}</small></div><span>${esc(s.ip_address||'Unknown address')}</span><span>${esc((s.user_agent||'Unknown client').slice(0,70))}</span><button class="secondary danger" data-session-revoke="${s.id}">Revoke</button></div>`).join('')||'<p class="muted">No active sessions.</p>'}`;$$('[data-session-revoke]').forEach(b=>b.onclick=()=>revokeSession(b.dataset.sessionRevoke))}else if(name==='audit'){const events=await api('/api/admin/audit');$('#auditAdmin').innerHTML=`<div class="panelhead"><div><h2>Audit & evidence</h2><p>Latest 250 tenant-scoped events with integrity hashes.</p></div><span class="chip">${events.length} events</span></div>${events.map(e=>`<div class="audit-row"><b>${esc(e.action)}</b> · ${esc(e.detail)}<small>${esc(e.actor)} · ${fmt(e.created_at)} · ${esc(e.event_hash.slice(0,12))}…</small></div>`).join('')}` }else if(name==='health'){const h=await api('/api/admin/health');$('#healthAdmin').innerHTML=`<div class="panelhead"><div><h2>System health</h2><p>Live checks for this FlowOps instance.</p></div><span class="connection-state ready"><i></i>${esc(h.status)}</span></div><div class="health-grid">${[['Database',h.database],['Active users',h.active_users],['Workspaces',h.workspaces],['Runbooks',h.runbooks],['Sessions',h.active_sessions],['Real-time',h.realtime],['Email',h.email_configured?'Ready':'Not configured'],['Secret encryption',h.credential_encryption_configured?'Ready':'Not configured']].map(([label,value])=>`<div class="health-metric"><span>${label}</span><b>${esc(value)}</b></div>`).join('')}</div>`}else if(name==='backups')return loadBackups()}catch(e){toast(e.message,true)}}
async function loadBackups(){try{const data=await api('/api/admin/backups');$('#backupAdmin').innerHTML=`<div class="panelhead"><div><h2>Database backups</h2><p>Automatic snapshot every ${data.interval_hours}h, retaining the last ${data.retain}. Point-in-time granularity is the backup interval, not per-transaction.</p></div><button class="primary" id="triggerBackup">⛁ Back up now</button></div><div id="backupList">${data.backups.length?data.backups.map(b=>`<div class="admin-list-row"><div><b>${esc(b.filename)}</b></div><span>${(b.size_bytes/1024).toFixed(0)} KB</span><span>${fmt(b.created_at)}</span></div>`).join(''):'<p class="muted">No backups yet. Trigger one manually, or wait for the next scheduled run.</p>'}</div>`;$('#triggerBackup').onclick=async()=>{try{await api('/api/admin/backups',{method:'POST',body:'{}'});toast('Backup created');loadBackups()}catch(e){toast(e.message,true)}}}catch(e){toast(e.message,true)}}
