const serviceOpsRenderDetail=renderDetail;renderDetail=function(){serviceOpsRenderDetail();const r=state.current;if(!r?.serviceops_ticket||!$('.detail-side'))return;const card=document.createElement('article');card.className='panel sidecard';card.innerHTML=`<div class="connection-head" style="padding:0 0 13px"><span class="provider-icon">SO</span><div><h2>ServiceOps record</h2><p>REST API v1 · last sync ${fmt(r.serviceops_synced_at)}</p></div></div><div class="kv"><span>Number</span><b>${esc(r.serviceops_ticket)}</b></div><div class="kv"><span>Type</span><b>${esc(r.serviceops_type||'—')}</b></div><div class="kv"><span>State</span><b>${esc(r.serviceops_state||'Not synchronized')}</b></div><div class="kv"><span>Priority</span><b>${esc(r.serviceops_priority||'—')}</b></div>${r.serviceops_title?`<p class="task-description">${esc(r.serviceops_title)}</p>`:''}<small class="muted">Request correlation: ${esc(r.serviceops_request_id||'—')}</small>`;$('.detail-side').prepend(card)};
const templateStyles=`.runbook-tags{display:flex;gap:6px;margin-top:4px}.type-tag{font-size:10px;color:var(--muted);background:#f4f3fb;border-radius:20px;padding:2px 8px}.template-category{margin-bottom:26px}.template-category h2{font-size:15px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em;margin:0 0 12px}.template-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:18px}.template-actions{display:flex;gap:8px;align-items:center;margin-top:14px}.template-actions .icon{margin-left:auto;background:transparent;border:1px solid var(--line);border-radius:7px;padding:6px 9px}`;document.head.append(Object.assign(document.createElement('style'),{textContent:templateStyles}));
async function createApiToken(){const name=prompt('Token name (e.g. "CI pipeline")');if(!name)return;const scopeInput=prompt('Scopes, comma-separated (runbooks:read, runbooks:write)','runbooks:read');const scopes=(scopeInput||'').split(',').map(s=>s.trim()).filter(Boolean);if(!scopes.length)return;try{const result=await api('/api/admin/api-tokens',{method:'POST',body:JSON.stringify({name,scopes})});alert(`Token created. Copy it now -- it will not be shown again:\n\n${result.token}`);loadAdminPanel('apiTokens')}catch(e){toast(e.message,true)}}
