async function createWebhook(){const name=prompt('Webhook name (e.g. "Deploy pipeline")');if(!name)return;const providerInput=(prompt('Destination type: "generic" (signed JSON), "slack", or "teams"','generic')||'generic').trim().toLowerCase();const provider=['generic','slack','teams'].includes(providerInput)?providerInput:'generic';const url=prompt(provider==='generic'?'Destination URL (https://...)':`${provider[0].toUpperCase()+provider.slice(1)} incoming webhook URL`);if(!url)return;try{const result=await api('/api/admin/webhooks',{method:'POST',body:JSON.stringify({name,url,provider,events:['*']})});alert(result.secret?`Webhook created. Copy the signing secret now -- it will not be shown again:\n\n${result.secret}\n\nVerify deliveries with header X-FlowOps-Signature: sha256=<HMAC-SHA256 of the body, using this secret>.`:`${provider[0].toUpperCase()+provider.slice(1)} webhook created. No separate secret -- the destination URL itself is the credential, per ${provider}'s own model.`);loadAdminPanel('webhooks')}catch(e){toast(e.message,true)}}
