const tokenLoadAdminPanel=loadAdminPanel;loadAdminPanel=async function(name){if(name==='apiTokens'){try{const tokens=await api('/api/admin/api-tokens');$('#apiTokenAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>API tokens</h2><p>Scoped bearer tokens for external automation. Secrets are shown once, at creation.</p></div><button class="primary" id="createApiToken">＋ New token</button></div>${tokens.map(t=>`<div class="admin-list-row"><div><b>${esc(t.name)}</b><small>${t.scopes.map(esc).join(', ')}</small></div><span>${t.last_used_at?'Used '+fmt(t.last_used_at):'Never used'}</span><span>${t.revoked_at?'Revoked':'Active'}</span>${t.revoked_at?'':`<button class="secondary danger" data-token-revoke="${t.id}">Revoke</button>`}</div>`).join('')||'<p class="muted">No API tokens yet.</p>'}</div>`;$('#createApiToken').onclick=createApiToken;$$('[data-token-revoke]').forEach(b=>b.onclick=()=>revokeApiToken(b.dataset.tokenRevoke))}catch(e){toast(e.message,true)}return}if(name==='webhooks'){try{const hooks=await api('/api/admin/webhooks');$('#webhookAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Outbound webhooks</h2><p>Signed HTTP callbacks on runbook and task state changes.</p></div><button class="primary" id="createWebhook">＋ New webhook</button></div>${hooks.map(h=>{const last=h.recent_deliveries[0];return `<div class="admin-list-row"><div><b>${esc(h.name)}</b><small>${h.provider!=="generic"?h.provider+" · ":""}${esc(h.url)}</small></div><span>${last?(last.success?'✓ Delivered':'✗ '+esc(last.error||'Failed')):'No deliveries yet'}</span><span>${h.active?'Active':'Paused'}</span><div class="inline-actions"><button class="secondary" data-webhook-test="${h.id}">Send test</button><button class="secondary danger" data-webhook-delete="${h.id}">Delete</button></div></div>`}).join('')||'<p class="muted">No webhooks yet.</p>'}</div>`;$('#createWebhook').onclick=createWebhook;$$('[data-webhook-test]').forEach(b=>b.onclick=()=>testWebhook(b.dataset.webhookTest));$$('[data-webhook-delete]').forEach(b=>b.onclick=()=>deleteWebhook(b.dataset.webhookDelete))}catch(e){toast(e.message,true)}return}return tokenLoadAdminPanel(name)};
async function loadTemplates(){try{const templates=await api('/api/templates');const byCategory={};templates.forEach(t=>{(byCategory[t.category]=byCategory[t.category]||[]).push(t)});const icons=['↗','⌁','✦','◈','⌘','◇'];let iconIndex=0;$('#templateGrid').innerHTML=Object.keys(byCategory).length?Object.entries(byCategory).map(([category,items])=>`<div class="template-category"><h2>${esc(category)}</h2><div class="template-row">${items.map(t=>{const icon=icons[iconIndex++%icons.length];return `<article><span class="templateicon">${icon}</span><h3>${esc(t.name)}</h3><p>${esc(t.description||`${t.task_count} tasks`)}</p><div class="template-actions"><button class="secondary" data-template-use="${t.id}">Use template</button><button class="icon" data-template-delete="${t.id}" aria-label="Delete ${esc(t.name)} template">🗑</button></div></article>`}).join('')}</div></div>`).join(''):'<div class="empty panel"><span>◇</span><h2>No templates yet</h2><p>Open a runbook and choose "Save as template" to create one.</p></div>';$$('[data-template-use]',$('#templateGrid')).forEach(b=>b.onclick=async()=>{const name=prompt('Name this runbook');if(!name)return;try{const created=await api(`/api/templates/${b.dataset.templateUse}/use`,{method:'POST',body:JSON.stringify({name})});await load();openRunbook(created.id);toast('Runbook created from template')}catch(e){toast(e.message,true)}});$$('[data-template-delete]',$('#templateGrid')).forEach(b=>b.onclick=async()=>{if(!confirm('Delete this template? This does not affect runbooks already created from it.'))return;try{await api(`/api/templates/${b.dataset.templateDelete}`,{method:'DELETE'});loadTemplates();toast('Template deleted')}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
