const csvRenderDetail=renderDetail;renderDetail=function(){csvRenderDetail();const r=state.current,actions=$('.detail-actions');if(!actions||!can('runbooks:edit'))return;const extra=document.createElement('div');extra.className='detail-actions';extra.style.marginLeft='auto';extra.innerHTML=`<button class="secondary" id="exportTasksCsv">⇩ Export CSV</button><button class="secondary" id="importTasksCsv">⇧ Import CSV</button><input type="file" id="importTasksCsvFile" accept=".csv,text/csv" hidden>`;actions.after(extra);$('#exportTasksCsv').onclick=()=>{window.open(`/api/runbooks/${r.id}/tasks.csv`,'_blank')};$('#importTasksCsv').onclick=()=>$('#importTasksCsvFile').click();$('#importTasksCsvFile').onchange=async(e)=>{const file=e.target.files[0];if(!file)return;try{const text=await file.text();const result=await api(`/api/runbooks/${r.id}/tasks-import`,{method:'POST',body:JSON.stringify({csv:text})});state.current=result;toast(`Imported tasks from CSV`);renderDetail()}catch(err){toast(err.message,true)}e.target.value=''}};
async function createWorkspaceManagerGrant(){const users=await api('/api/admin/users');const workspaces=await api('/api/workspaces');const username=prompt(`User to grant (username): ${users.map(u=>u.username).join(', ')}`);const user=users.find(u=>u.username===username);if(!user)return toast('User not found',true);const wsname=prompt(`Workspace: ${workspaces.map(w=>w.name).join(', ')}`);const ws=workspaces.find(w=>w.name===wsname);if(!ws)return toast('Workspace not found',true);try{await api('/api/admin/workspace-managers',{method:'POST',body:JSON.stringify({user_id:user.id,workspace_id:ws.id})});loadAdminPanel('scopedRoles');toast('Workspace Manager grant added')}catch(e){toast(e.message,true)}}
