async function deleteCentralTeam(teamId){if(!confirm('Delete this central team? It must not be linked into any runbook.'))return;try{await api(`/api/central-teams/${teamId}`,{method:'DELETE'});loadAdminPanel('centralTeams')}catch(e){toast(e.message,true)}}
async function createCustomField(){const entityType=(prompt('Applies to: "runbook" or "task"','runbook')||'').trim().toLowerCase();if(!['runbook','task'].includes(entityType))return toast('Must be "runbook" or "task"',true);const name=prompt('Field name (e.g. "Change risk")');if(!name)return;const fieldType=(prompt('Type: text, number, date, boolean, or select','text')||'text').trim().toLowerCase();if(!['text','number','date','boolean','select'].includes(fieldType))return toast('Invalid field type',true);let options=[];if(fieldType==='select'){const raw=prompt('Options, comma-separated');options=(raw||'').split(',').map(s=>s.trim()).filter(Boolean)}try{await api('/api/custom-fields',{method:'POST',body:JSON.stringify({entity_type:entityType,name,field_type:fieldType,options})});loadAdminPanel('customFields');toast('Custom field created')}catch(e){toast(e.message,true)}}
async function deleteCustomField(id){if(!confirm('Delete this custom field? Existing values will be removed too.'))return;try{await api(`/api/custom-fields/${id}`,{method:'DELETE'});loadAdminPanel('customFields')}catch(e){toast(e.message,true)}}
const teamsAndFieldsLoadAdminPanel=loadAdminPanel;loadAdminPanel=async function(name){if(name==='centralTeams'){try{const teams=await api('/api/central-teams');$('#centralTeamAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Central teams</h2><p>A shared roster you can link into any runbook's teams; membership changes propagate live.</p></div><button class="primary" data-create-central-team>＋ New team</button></div>${teams.map(t=>`<div class="admin-list-row"><div><b>${esc(t.name)}</b><small>${t.members.length} member${t.members.length===1?'':'s'} · linked into ${t.linked_runbooks} runbook${t.linked_runbooks===1?'':'s'}</small></div><span>${t.members.map(m=>esc(m.display_name)).join(', ')||'No members'}</span><div class="inline-actions"><button class="secondary" data-add-member="${t.id}">＋ Member</button>${t.members.map(m=>`<button class="secondary danger" data-remove-member="${t.id}:${m.id}" title="Remove ${esc(m.display_name)}">−${esc(m.display_name.split(' ')[0])}</button>`).join('')}<button class="secondary danger" data-delete-team="${t.id}">Delete</button></div></div>`).join('')||'<p class="muted">No central teams yet.</p>'}</div>`;$('[data-create-central-team]').onclick=createCentralTeam;$$('[data-add-member]').forEach(b=>b.onclick=()=>addCentralTeamMember(b.dataset.addMember));$$('[data-remove-member]').forEach(b=>{const[t,u]=b.dataset.removeMember.split(':');b.onclick=()=>removeCentralTeamMember(t,u)});$$('[data-delete-team]').forEach(b=>b.onclick=()=>deleteCentralTeam(b.dataset.deleteTeam))}catch(e){toast(e.message,true)}return}if(name==='customFields'){try{const fields=await api('/api/custom-fields');$('#customFieldAdmin').innerHTML=`<div class="panel"><div class="panelhead"><div><h2>Custom fields</h2><p>Typed fields captured on runbooks or tasks, editable from their detail view.</p></div><button class="primary" data-create-field>＋ New field</button></div>${fields.map(f=>`<div class="admin-list-row"><div><b>${esc(f.name)}</b><small>${esc(f.entity_type)} · ${esc(f.field_type)}${f.options.length?' · '+f.options.map(esc).join(', '):''}</small></div><span>${f.required?'Required':'Optional'}</span><button class="secondary danger" data-delete-field="${f.id}">Delete</button></div>`).join('')||'<p class="muted">No custom fields yet.</p>'}</div>`;$('[data-create-field]').onclick=createCustomField;$$('[data-delete-field]').forEach(b=>b.onclick=()=>deleteCustomField(b.dataset.deleteField))}catch(e){toast(e.message,true)}return}return teamsAndFieldsLoadAdminPanel(name)};
async function linkCentralTeamIntoRunbook(){const r=state.current;try{const teams=await api('/api/central-teams');const name=prompt(`Link a central team into this runbook: ${teams.map(t=>t.name).join(', ')}`);const team=teams.find(t=>t.name===name);if(!team)return;await api(`/api/runbooks/${r.id}/teams`,{method:'POST',body:JSON.stringify({central_team_id:team.id})});state.current=await api(`/api/runbooks/${r.id}`);renderDetail();toast(`Linked ${team.name}`)}catch(e){toast(e.message,true)}}
async function editRunbookCustomFields(){const r=state.current;try{const defs=(await api('/api/custom-fields?entity_type=runbook')).filter(d=>true);const values={};for(const d of defs){const current=r.custom_fields?.[d.name]||'';const next=prompt(`${d.name}${d.options.length?` (options: ${d.options.join(', ')})`:''}`,current);if(next!==null)values[d.id]=next}if(!Object.keys(values).length)return;const updated=await api(`/api/runbooks/${r.id}`,{method:'PATCH',body:JSON.stringify({custom_fields:values})});state.current=updated;renderDetail();toast('Custom fields updated')}catch(e){toast(e.message,true)}}
const customFieldsRenderDetail=renderDetail;renderDetail=function(){customFieldsRenderDetail();const r=state.current,side=$('.detail-side');if(!side||!can('runbooks:edit'))return;const card=document.createElement('article');card.className='panel sidecard';const cf=r.custom_fields||{};card.innerHTML=`<div class="panelhead"><div><h2>Custom fields</h2><p>Workspace-defined runbook attributes</p></div><button class="secondary" id="editCustomFields">✎ Edit</button></div>${Object.keys(cf).length?Object.entries(cf).map(([k,v])=>`<div class="kv"><span>${esc(k)}</span><b>${esc(v||'—')}</b></div>`).join(''):'<p class="muted">No custom fields defined for this workspace yet.</p>'}<button class="secondary" id="linkCentralTeam" style="margin-top:12px">⇄ Link central team</button>`;side.append(card);$('#editCustomFields').onclick=editRunbookCustomFields;$('#linkCentralTeam').onclick=linkCentralTeamIntoRunbook};
function linkify(text){return esc(text).replace(/\n/g,'<br>').replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener noreferrer">$1</a>')}
const homeRenderDetail=renderDetail;renderDetail=function(){homeRenderDetail();const r=state.current,side=$('.detail-side');if(!side)return;const card=document.createElement('article');card.className='panel sidecard';card.innerHTML=`<div class="panelhead"><div><h2>Runbook home</h2><p>Operational instructions and links</p></div>${can('runbooks:edit')?'<button class="secondary" id="editHomeContent">✎ Edit</button>':''}</div>${r.home_content?`<p class="task-description">${linkify(r.home_content)}</p>`:'<p class="muted">No instructions added yet.</p>'}`;side.prepend(card);const editBtn=$('#editHomeContent');if(editBtn)editBtn.onclick=async()=>{const next=prompt('Runbook home content (instructions, links, one per line):',r.home_content||'');if(next===null)return;try{state.current=await api(`/api/runbooks/${r.id}`,{method:'PATCH',body:JSON.stringify({home_content:next})});renderDetail();toast('Runbook home updated')}catch(e){toast(e.message,true)}}};
const reviewRenderDetail=renderDetail;renderDetail=function(){reviewRenderDetail();const r=state.current,side=$('.detail-side');if(!side||r.status!=='complete')return;const card=document.createElement('article');card.className='panel sidecard';if(r.review){card.innerHTML=`<h2>Post-implementation review</h2><div class="kv"><span>What went well</span><b>${esc(r.review.what_went_well||'—')}</b></div><div class="kv"><span>What went wrong</span><b>${esc(r.review.what_went_wrong||'—')}</b></div><div class="kv"><span>Follow-up actions</span><b>${esc(r.review.follow_up_actions||'—')}</b></div><small class="muted">Reviewed by ${esc(r.review.reviewed_by)} · ${fmt(r.review.reviewed_at)}</small>`}else if(can('runbooks:edit')){card.innerHTML=`<div class="panelhead"><div><h2>Post-implementation review</h2><p>Record lessons learned now that this runbook is complete.</p></div><button class="primary" id="addReview">＋ Add review</button></div>`}else return;side.append(card);const addBtn=$('#addReview');if(addBtn)addBtn.onclick=async()=>{const what_went_well=prompt('What went well?')||'';const what_went_wrong=prompt('What went wrong?')||'';const follow_up_actions=prompt('Follow-up actions?')||'';try{state.current=await api(`/api/runbooks/${r.id}/review`,{method:'PATCH',body:JSON.stringify({what_went_well,what_went_wrong,follow_up_actions})});renderDetail();toast('Review recorded')}catch(e){toast(e.message,true)}}};
async function linkParentRunbook(){const r=state.current;try{const all=(await api('/api/runbooks')).filter(x=>x.id!==r.id);const name=prompt(`Set parent runbook (leave blank to unlink): ${all.map(x=>x.name).join(', ')}`,r.parent_runbook?r.parent_runbook.name:'');if(name===null)return;const target=all.find(x=>x.name===name);if(name.trim()&&!target)return toast('Runbook not found',true);const updated=await api(`/api/runbooks/${r.id}`,{method:'PATCH',body:JSON.stringify({parent_runbook_id:target?target.id:null})});state.current=updated;renderDetail();toast(target?`Linked under ${target.name}`:'Unlinked from parent')}catch(e){toast(e.message,true)}}
const linkedRenderDetail=renderDetail;renderDetail=function(){linkedRenderDetail();const r=state.current,side=$('.detail-side');if(!side||!can('runbooks:edit'))return;const card=document.createElement('article');card.className='panel sidecard';card.innerHTML=`<div class="panelhead"><div><h2>Linked runbooks</h2><p>${r.parent_runbook?'Child of a parent runbook':r.child_runbooks?.length?'Parent of linked child runbooks':'Not linked to any other runbook'}</p></div><button class="secondary" id="linkParentRunbook">⇄ Set parent</button></div>${r.parent_runbook?`<div class="kv"><span>Parent</span><b>${esc(r.parent_runbook.name)} (${esc(r.parent_runbook.status)})</b></div>`:''}${r.child_runbooks&&r.child_runbooks.length?`<p class="muted" style="margin:10px 0 4px">Aggregate progress: <b>${r.aggregate_progress}%</b> · status: <b>${esc(r.aggregate_status)}</b></p>`+r.child_runbooks.map(c=>`<div class="kv"><span>${esc(c.name)}</span><b>${c.progress}% · ${esc(c.status)}</b></div>`).join(''):''}`;side.append(card);$('#linkParentRunbook').onclick=linkParentRunbook};
async function bulkEditTasks(){const r=state.current;if(!r.tasks.length)return toast('No tasks to edit',true);const list=r.tasks.map((t,i)=>`${i+1}. ${t.title}`).join('\n');const selection=prompt(`Select task numbers to bulk-edit, comma-separated:\n\n${list}`);if(!selection)return;const indexes=selection.split(',').map(s=>parseInt(s.trim(),10)-1).filter(i=>i>=0&&i<r.tasks.length);if(!indexes.length)return toast('No valid task numbers selected',true);const task_ids=indexes.map(i=>r.tasks[i].id);const durationInput=prompt('New duration in minutes (leave blank to skip)');const body={task_ids};if(durationInput&&durationInput.trim())body.duration=parseInt(durationInput.trim(),10);if(Object.keys(body).length<2)return toast('Nothing to update',true);try{const result=await api(`/api/runbooks/${r.id}/tasks-bulk-edit`,{method:'POST',body:JSON.stringify(body)});state.current=result;renderDetail();toast(`Updated ${task_ids.length} task${task_ids.length===1?'':'s'}`)}catch(e){toast(e.message,true)}}
const bulkEditRenderDetail=renderDetail;renderDetail=function(){bulkEditRenderDetail();const actions=$('.detail-actions');if(!actions||!can('runbooks:edit')||$('#bulkEditTasks'))return;const btn=document.createElement('button');btn.className='secondary';btn.id='bulkEditTasks';btn.textContent='☰ Bulk edit';btn.onclick=bulkEditTasks;actions.append(btn)};
async function saveSelectionAsSnippet(){const r=state.current;if(!r.tasks.length)return toast('No tasks to save',true);const list=r.tasks.map((t,i)=>`${i+1}. ${t.title}`).join('\n');const selection=prompt(`Select task numbers to save as a reusable snippet, comma-separated (max 100):\n\n${list}`);if(!selection)return;const indexes=selection.split(',').map(s=>parseInt(s.trim(),10)-1).filter(i=>i>=0&&i<r.tasks.length);if(!indexes.length)return toast('No valid task numbers selected',true);const name=prompt('Snippet name:');if(!name)return;try{await api(`/api/runbooks/${r.id}/save-as-snippet`,{method:'POST',body:JSON.stringify({name,task_ids:indexes.map(i=>r.tasks[i].id)})});toast(`Saved snippet "${name}"`)}catch(e){toast(e.message,true)}}
async function insertSnippet(){const r=state.current;try{const snippets=await api('/api/snippets');if(!snippets.length)return toast('No snippets saved yet',true);const name=prompt(`Insert which snippet?\n\n${snippets.map(s=>`${s.name} (${s.task_count} tasks)`).join('\n')}`);if(!name)return;const snippet=snippets.find(s=>s.name===name);if(!snippet)return toast('Snippet not found',true);state.current=await api(`/api/runbooks/${r.id}/insert-snippet`,{method:'POST',body:JSON.stringify({snippet_id:snippet.id})});renderDetail();toast(`Inserted ${snippet.task_count} tasks from "${snippet.name}"`)}catch(e){toast(e.message,true)}}
const snippetRenderDetail=renderDetail;renderDetail=function(){snippetRenderDetail();const actions=$('.detail-actions');if(!actions||!can('runbooks:edit')||$('#saveSnippet'))return;const saveBtn=document.createElement('button');saveBtn.className='secondary';saveBtn.id='saveSnippet';saveBtn.textContent='✂ Save snippet';saveBtn.onclick=saveSelectionAsSnippet;const insertBtn=document.createElement('button');insertBtn.className='secondary';insertBtn.id='insertSnippet';insertBtn.textContent='＋ Insert snippet';insertBtn.onclick=insertSnippet;actions.append(saveBtn,insertBtn)};
async function approveRunbook(){const r=state.current;try{state.current=await api(`/api/runbooks/${r.id}/approve`,{method:'POST',body:'{}'});renderDetail();toast('Runbook approved')}catch(e){toast(e.message,true)}}
const approvalRenderDetail=renderDetail;renderDetail=function(){approvalRenderDetail();const r=state.current;if(!r.runbook_type_requires_approval)return;const actions=$('.detail-actions');if(!actions)return;const badge=document.createElement('span');badge.className=r.approved_at?'chip complete':'chip live';badge.textContent=r.approved_at?`✓ Approved by ${r.approved_by}`:'⏳ Approval required before Live';actions.prepend(badge);if(!r.approved_at&&can('admin:access')){const btn=document.createElement('button');btn.className='primary';btn.textContent='✓ Approve';btn.onclick=approveRunbook;actions.append(btn)}};
async function createRunbookType(){const name=prompt('Runbook type name (e.g. "High-risk change")');if(!name)return;const requiresApproval=confirm('Require approval before this type of runbook can go Live?');try{await api('/api/runbook-types',{method:'POST',body:JSON.stringify({name,requires_approval:requiresApproval})});toast('Runbook type created')}catch(e){toast(e.message,true)}}
const runbookTypeLoadAdmin=loadAdmin;loadAdmin=async function(){await runbookTypeLoadAdmin();const area=$('#workspaceControl');if(!area||$('#createRunbookType'))return;const btn=document.createElement('button');btn.className='secondary';btn.id='createRunbookType';btn.textContent='＋ New runbook type';btn.style.marginTop='10px';btn.onclick=createRunbookType;area.querySelector('article').append(btn)};
async function loadDelayReport(){try{const rows=await api('/api/reports/delay');$('#delayReportTable').innerHTML=rows.length?`<div class="table"><div class="trow head" style="grid-template-columns:1.5fr 1.5fr 1fr 1fr .8fr .8fr"><span>Runbook</span><span>Task</span><span>Stream</span><span>Owner</span><span>Status</span><span>Delay</span></div>${rows.map(r=>`<div class="trow" style="grid-template-columns:1.5fr 1.5fr 1fr 1fr .8fr .8fr;cursor:default"><b>${esc(r.runbook)}</b><span>${esc(r.task)}</span><span>${esc(r.stream)}</span><span>${esc(r.owner)}</span><span>${esc(r.status)}</span><span>${r.delay_minutes==='in progress'?'⏳ in progress':`${r.delay_minutes} min`}</span></div>`).join('')}</div>`:'<div class="empty panel"><span>✓</span><h2>No delays found</h2><p>Every task across every runbook is on schedule.</p></div>'}catch(e){toast(e.message,true)}}
const reportShow=show;show=function(view){reportShow(view);if(view==='analytics')loadDelayReport()};
$('#printDelayReport').onclick=()=>window.print();
$('#exportDelayReportCsv').onclick=()=>window.open('/api/reports/delay.csv','_blank');
const printStyles=`@media print{aside,header,.header-actions,#toast{display:none!important}.view{display:none!important}.view.active{display:block!important;padding:0!important}}`;document.head.append(Object.assign(document.createElement('style'),{textContent:printStyles}));
async function purgeAuditRetention(){if(!confirm('Purge audit events older than the configured retention period? This cannot be undone -- export first if you need a copy.'))return;try{const result=await api('/api/admin/audit/purge',{method:'POST',body:'{}'});toast(`Purged ${result.purged} event${result.purged===1?'':'s'}`);loadAdminPanel('audit')}catch(e){toast(e.message,true)}}
const retentionLoadAdminPanel=loadAdminPanel;loadAdminPanel=async function(name){await retentionLoadAdminPanel(name);if(name==='audit'&&!$('#purgeAuditRetention')){const head=$('#auditAdmin .panelhead');if(head){const btn=document.createElement('button');btn.className='secondary danger';btn.id='purgeAuditRetention';btn.textContent='🗑 Purge by retention';btn.onclick=purgeAuditRetention;head.append(btn)}}};
const baseApplyIdentity=applyIdentity;
applyIdentity=function(){baseApplyIdentity();const u=state.user;const avatarEl=$('#profile .avatar');if(u.avatar_path){avatarEl.innerHTML=`<img src="/avatar/${u.id}?v=${encodeURIComponent(u.avatar_path)}" alt="">`}else{avatarEl.innerHTML='';avatarEl.textContent=u.display_name.split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()}};
function showProfileTab(name){$$('.profile-tab').forEach(b=>b.classList.toggle('active',b.dataset.ptab===name));$$('.profile-pane').forEach(p=>p.classList.toggle('active',p.id===`profileTab${name[0].toUpperCase()}${name.slice(1)}`))}
$$('.profile-tab').forEach(b=>b.onclick=()=>showProfileTab(b.dataset.ptab));
function openProfileModal(){const u=state.user;showProfileTab('details');const f=$('#profileForm');f.display_name.value=u.display_name||'';f.email.value=u.email||'';f.title.value=u.title||'';f.timezone.value=u.timezone||'';f.date_format.value=u.date_format||'system';const preview=$('#profileAvatarPreview');if(u.avatar_path){preview.src=`/avatar/${u.id}?v=${encodeURIComponent(u.avatar_path)}`;preview.style.display=''}else{preview.removeAttribute('src');preview.style.display='none'}$('#passwordForm').reset();$('#profileModal').showModal()}
$('#openProfile').onclick=openProfileModal;
$$('.close-profile').forEach(b=>b.onclick=()=>$('#profileModal').close());
$('#profileForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));try{const updated=await api('/api/profile',{method:'PATCH',body:JSON.stringify(data)});state.user={...state.user,...updated};applyIdentity();toast('Profile updated')}catch(err){toast(err.message,true)}};
$('#avatarFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>5*1024*1024){toast('Profile picture must be smaller than 5 MB',true);e.target.value='';return}const reader=new FileReader();reader.onload=async()=>{try{const updated=await api('/api/profile/avatar',{method:'POST',body:JSON.stringify({avatar_base64:reader.result})});state.user.avatar_path=updated.avatar_path;applyIdentity();$('#profileAvatarPreview').src=`/avatar/${state.user.id}?v=${encodeURIComponent(updated.avatar_path)}`;$('#profileAvatarPreview').style.display='';toast('Profile picture updated')}catch(err){toast(err.message,true)}finally{e.target.value=''}};reader.readAsDataURL(file)};
$('#passwordForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,data=Object.fromEntries(new FormData(form));try{await api('/api/profile/change-password',{method:'POST',body:JSON.stringify(data)});form.reset();toast('Password changed. Your other sessions have been signed out.')}catch(err){toast(err.message,true)}};
$('#exportMyData').onclick=()=>window.open('/api/profile/export','_blank');
const cutoverStyleRenderDetail=renderDetail;
renderDetail=function(){cutoverStyleRenderDetail();const r=state.current,taskRoot=$('#tasks');if(!taskRoot||!r)return;$$('.task',taskRoot).forEach((el,i)=>{const t=r.tasks[i];if(!t)return;const sc=streamColor(t.stream);const num=el.querySelector('.tasknum');if(num)num.style.setProperty('--stream-color',sc);const small=el.querySelector('small');if(small&&!small.querySelector('.stream-dot')){const dot=document.createElement('i');dot.className='stream-dot';dot.style.background=sc;small.prepend(dot)}if(!el.querySelector('.task-avatar')){const owner=t.owner_display||t.owner||'';const av=document.createElement('span');av.className='task-avatar';av.textContent=owner?initials(owner):'—';av.style.background=owner?streamColor(owner):'#c7cbdc';av.title=owner||'Unassigned';el.appendChild(av)}})};
boot();
